package report

import "time"

// DailyStat 是单日答题统计。
type DailyStat struct {
	Date     string `json:"date"`
	Answered int    `json:"answered"`
	Correct  int    `json:"correct"`
}

// SubjectStat 是单学科统计。
type SubjectStat struct {
	Answered int         `json:"answered"`
	Correct  int         `json:"correct"`
	Accuracy float64     `json:"accuracy"`
	Trend    []DailyStat `json:"trend,omitempty"`
}

// Report 是成长报告。
type Report struct {
	ID          string                 `json:"id"`
	ChildID     string                 `json:"child_id"`
	Period      string                 `json:"period"`
	PeriodStart time.Time              `json:"period_start"`
	PeriodEnd   time.Time              `json:"period_end"`
	SubjectStats map[string]SubjectStat `json:"subject_stats"`
	FunStats    SubjectStat            `json:"fun_stats"`
	WatchMinutes int                   `json:"watch_minutes"`
	GeneratedAt time.Time              `json:"generated_at"`
}

// Error 是报告业务错误。
type Error struct {
	Status  int
	Code    string
	Message string
}

func (e *Error) Error() string { return e.Message }

func newError(status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message}
}

package report

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type repository struct {
	pool *pgxpool.Pool
}

func newRepository(pool *pgxpool.Pool) *repository {
	return &repository{pool: pool}
}

type answerRow struct {
	Date     string
	Subject  string
	Answered int
	Correct  int
}

func (r *repository) aggregateAnswers(ctx context.Context, childID string, start, end time.Time, timezone string) ([]answerRow, error) {
	rows, err := r.pool.Query(ctx, `
		select to_char((a.answered_at at time zone $4)::date, 'YYYY-MM-DD') as day,
		       q.subject_code,
		       count(*)::int,
		       sum(case when a.is_correct then 1 else 0 end)::int
		from answer_log a
		join question q on q.id = a.question_id
		where a.child_id = $1 and a.answered_at >= $2 and a.answered_at < $3
		group by 1, 2
		order by 1`, childID, start, end, timezone)
	if err != nil {
		return nil, fmt.Errorf("aggregate answers: %w", err)
	}
	defer rows.Close()

	items := make([]answerRow, 0)
	for rows.Next() {
		var row answerRow
		if err := rows.Scan(&row.Date, &row.Subject, &row.Answered, &row.Correct); err != nil {
			return nil, err
		}
		items = append(items, row)
	}
	return items, rows.Err()
}

func (r *repository) watchMinutes(ctx context.Context, childID string, start, end time.Time) (int, error) {
	var seconds int
	err := r.pool.QueryRow(ctx, `
		select coalesce(sum(watched_seconds), 0)::int
		from watch_log
		where child_id = $1 and start_at >= $2 and start_at < $3`,
		childID, start, end).Scan(&seconds)
	if err != nil {
		return 0, err
	}
	return (seconds + 30) / 60, nil
}

func (r *repository) upsert(ctx context.Context, childID, period string, start time.Time,
	subjectStats, funStats map[string]any, watchMinutes int) (string, time.Time, error) {
	subjects, _ := json.Marshal(subjectStats)
	fun, _ := json.Marshal(funStats)

	var id string
	var generatedAt time.Time
	err := r.pool.QueryRow(ctx, `
		insert into growth_report (child_id, period, period_start, subject_stats, fun_stats, watch_minutes, generated_at)
		values ($1, $2, $3, $4::jsonb, $5::jsonb, $6, now())
		on conflict (child_id, period, period_start) do update set
			subject_stats = excluded.subject_stats,
			fun_stats = excluded.fun_stats,
			watch_minutes = excluded.watch_minutes,
			generated_at = now()
		returning id, generated_at`,
		childID, period, start, string(subjects), string(fun), watchMinutes).Scan(&id, &generatedAt)
	return id, generatedAt, err
}

func (r *repository) childTimezone(ctx context.Context, childID string) (string, error) {
	var timezone string
	err := r.pool.QueryRow(ctx, `
		select coalesce(wr.timezone, 'Asia/Shanghai')
		from child_profile c
		left join watch_rule wr on wr.child_id = c.id
		where c.id = $1`, childID).Scan(&timezone)
	return timezone, err
}

func (r *repository) list(ctx context.Context, accountID, childID, period string, limit int) ([]Report, error) {
	rows, err := r.pool.Query(ctx, `
		select gr.id, gr.child_id, gr.period, gr.period_start,
		       gr.subject_stats::text, gr.fun_stats::text, gr.watch_minutes, gr.generated_at
		from growth_report gr
		where gr.child_id = $1 and gr.period = $2
		  and exists (
		      select 1 from child_profile c
		      join family_member fm on fm.family_id = c.family_id
		      where c.id = gr.child_id and fm.account_id = $3
		  )
		order by gr.period_start desc
		limit $4`, childID, period, accountID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	reports := make([]Report, 0)
	for rows.Next() {
		var rep Report
		var subjects, fun string
		if err := rows.Scan(&rep.ID, &rep.ChildID, &rep.Period, &rep.PeriodStart,
			&subjects, &fun, &rep.WatchMinutes, &rep.GeneratedAt); err != nil {
			return nil, err
		}
		rep.SubjectStats = map[string]SubjectStat{}
		if err := json.Unmarshal([]byte(subjects), &rep.SubjectStats); err != nil {
			return nil, err
		}
		if err := json.Unmarshal([]byte(fun), &rep.FunStats); err != nil {
			return nil, err
		}
		reports = append(reports, rep)
	}
	return reports, rows.Err()
}

func (r *repository) children(ctx context.Context) ([]childRow, error) {
	rows, err := r.pool.Query(ctx, `
		select c.id, coalesce(wr.timezone, 'Asia/Shanghai')
		from child_profile c
		left join watch_rule wr on wr.child_id = c.id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	children := make([]childRow, 0)
	for rows.Next() {
		var child childRow
		if err := rows.Scan(&child.ID, &child.Timezone); err != nil {
			return nil, err
		}
		children = append(children, child)
	}
	return children, rows.Err()
}

func (r *repository) ownsChild(ctx context.Context, accountID, childID string) (bool, error) {
	var owns bool
	err := r.pool.QueryRow(ctx, `
		select exists (
			select 1 from child_profile c
			join family_member fm on fm.family_id = c.family_id
			where c.id = $1 and fm.account_id = $2
		)`, childID, accountID).Scan(&owns)
	return owns, err
}

type childRow struct {
	ID       string
	Timezone string
}

func isNoRows(err error) bool {
	return err == pgx.ErrNoRows
}

package report

import (
	"context"
	"fmt"
	"log/slog"
	"math"
	"sort"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Service 负责成长报告聚合与查询。
type Service struct {
	repo   *repository
	logger *slog.Logger
}

// New 构造报告服务。
func New(pool *pgxpool.Pool, logger *slog.Logger) *Service {
	return &Service{repo: newRepository(pool), logger: logger}
}

// List 返回孩子的周/月报告。
func (s *Service) List(ctx context.Context, accountID, childID, period string, limit int) ([]Report, error) {
	if period != "week" && period != "month" {
		return nil, newError(422, "VALIDATION_ERROR", "period 需为 week 或 month")
	}
	owns, err := s.repo.ownsChild(ctx, accountID, childID)
	if err != nil {
		return nil, err
	}
	if !owns {
		return nil, newError(404, "CHILD_NOT_FOUND", "孩子档案不存在")
	}
	if limit <= 0 || limit > 52 {
		limit = 8
	}
	reports, err := s.repo.list(ctx, accountID, childID, period, limit)
	if err != nil {
		return nil, err
	}
	for i := range reports {
		reports[i].PeriodEnd = periodEnd(reports[i].Period, reports[i].PeriodStart)
	}
	return reports, nil
}

// Generate 聚合指定周期的报告（幂等）。
func (s *Service) Generate(ctx context.Context, childID, period string, start time.Time) (Report, error) {
	if period != "week" && period != "month" {
		return Report{}, newError(422, "VALIDATION_ERROR", "period 需为 week 或 month")
	}
	timezone, err := s.repo.childTimezone(ctx, childID)
	if err != nil {
		if isNoRows(err) {
			return Report{}, newError(404, "CHILD_NOT_FOUND", "孩子档案不存在")
		}
		return Report{}, err
	}
	location, err := time.LoadLocation(timezone)
	if err != nil {
		location = time.UTC
	}
	start = periodStart(period, start.In(location), location)
	end := periodEnd(period, start)

	rows, err := s.repo.aggregateAnswers(ctx, childID, start, end, timezone)
	if err != nil {
		return Report{}, err
	}
	subjects := map[string]SubjectStat{}
	fun := SubjectStat{}
	for _, row := range rows {
		stat := SubjectStat{Answered: row.Answered, Correct: row.Correct}
		if row.Subject == "fun" {
			fun.Answered += row.Answered
			fun.Correct += row.Correct
			fun.Trend = append(fun.Trend, DailyStat{Date: row.Date, Answered: row.Answered, Correct: row.Correct})
			continue
		}
		current := subjects[row.Subject]
		current.Answered += row.Answered
		current.Correct += row.Correct
		current.Trend = append(current.Trend, DailyStat{Date: row.Date, Answered: row.Answered, Correct: row.Correct})
		subjects[row.Subject] = current
	}
	for subject, stat := range subjects {
		stat.Accuracy = accuracy(stat.Answered, stat.Correct)
		sort.Slice(stat.Trend, func(i, j int) bool { return stat.Trend[i].Date < stat.Trend[j].Date })
		subjects[subject] = stat
	}
	fun.Accuracy = accuracy(fun.Answered, fun.Correct)
	sort.Slice(fun.Trend, func(i, j int) bool { return fun.Trend[i].Date < fun.Trend[j].Date })

	watchMinutes, err := s.repo.watchMinutes(ctx, childID, start, end)
	if err != nil {
		return Report{}, err
	}
	payload := make(map[string]any, len(subjects))
	for subject, stat := range subjects {
		payload[subject] = stat
	}
	funPayload := map[string]any{
		"answered": fun.Answered,
		"correct":  fun.Correct,
		"accuracy": fun.Accuracy,
		"trend":    fun.Trend,
	}
	id, generatedAt, err := s.repo.upsert(ctx, childID, period, start, payload, funPayload, watchMinutes)
	if err != nil {
		return Report{}, err
	}
	return Report{
		ID:           id,
		ChildID:      childID,
		Period:       period,
		PeriodStart:  start,
		PeriodEnd:    end,
		SubjectStats: subjects,
		FunStats:     fun,
		WatchMinutes: watchMinutes,
		GeneratedAt:  generatedAt,
	}, nil
}

// GenerateAll 为所有孩子生成当前与前一周/月报告。
func (s *Service) GenerateAll(ctx context.Context) (int, error) {
	children, err := s.repo.children(ctx)
	if err != nil {
		return 0, err
	}
	generated := 0
	for _, child := range children {
		location, err := time.LoadLocation(child.Timezone)
		if err != nil {
			location = time.UTC
		}
		now := time.Now().In(location)
		targets := []struct {
			period string
			start  time.Time
		}{
			{"week", periodStart("week", now, location)},
			{"week", periodStart("week", now.AddDate(0, 0, -7), location)},
			{"month", periodStart("month", now, location)},
			{"month", periodStart("month", now.AddDate(0, -1, 0), location)},
		}
		for _, target := range targets {
			if _, err := s.Generate(ctx, child.ID, target.period, target.start); err != nil {
				s.logger.Error("generate report", "error", err, "child_id", child.ID,
					"period", target.period, "start", target.start)
				continue
			}
			generated++
		}
	}
	return generated, nil
}

func periodStart(period string, at time.Time, location *time.Location) time.Time {
	local := at.In(location)
	switch period {
	case "week":
		offset := (int(local.Weekday()) + 6) % 7 // Monday = 0
		return time.Date(local.Year(), local.Month(), local.Day()-offset, 0, 0, 0, 0, location)
	default:
		return time.Date(local.Year(), local.Month(), 1, 0, 0, 0, 0, location)
	}
}

func periodEnd(period string, start time.Time) time.Time {
	if period == "week" {
		return start.AddDate(0, 0, 7)
	}
	return start.AddDate(0, 1, 0)
}

func accuracy(answered, correct int) float64 {
	if answered == 0 {
		return 0
	}
	return math.Round(float64(correct)/float64(answered)*1000) / 1000
}

