import http from 'k6/http'
import { check } from 'k6'

// 用法：
//   BASE=http://localhost:8080/v1 DEVICE_TOKEN=... k6 run deploy/k6/load.js
//   TARGET=heartbeat GRANT_ID=... k6 run deploy/k6/load.js
//
// 说明：答题/会话接口有设备级限流，压测前应在预发环境关闭限流，
// 或使用多个设备令牌分摊。默认压测 /child/context。

const BASE = __ENV.BASE || 'http://localhost:8080/v1'
const TOKEN = __ENV.DEVICE_TOKEN || ''
const TARGET = __ENV.TARGET || 'context'
const RATE = Number(__ENV.RATE || 1000)
const DURATION = __ENV.DURATION || '30s'

export const options = {
  scenarios: {
    load: {
      executor: 'constant-arrival-rate',
      rate: RATE,
      timeUnit: '1s',
      duration: DURATION,
      preAllocatedVUs: Math.max(50, Math.ceil(RATE / 50)),
      maxVUs: Math.max(200, RATE),
    },
  },
  thresholds: {
    http_req_duration: ['p(95)<200'],
    http_req_failed: ['rate<0.01'],
  },
}

const headers = {
  Authorization: `Bearer ${TOKEN}`,
  'Content-Type': 'application/json',
}

export default function () {
  if (!TOKEN) {
    throw new Error('DEVICE_TOKEN is required')
  }
  let res
  if (TARGET === 'heartbeat') {
    const grantID = __ENV.GRANT_ID
    if (!grantID) {
      throw new Error('GRANT_ID is required for heartbeat target')
    }
    res = http.post(`${BASE}/watch/grants/${grantID}/heartbeat`,
      JSON.stringify({ foreground_app: 'com.example.video', paused: false }), { headers })
  } else {
    res = http.get(`${BASE}/child/context`, { headers })
  }
  check(res, { 'status 200': (r) => r.status === 200 })
}

package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"sort"
	"strings"
	"sync"
	"time"
)

func main() {
	base := flag.String("base", "http://localhost:8080", "服务地址")
	path := flag.String("path", "/v1/child/context", "压测路径")
	token := flag.String("token", "", "设备令牌（可选）")
	rate := flag.Int("rate", 1000, "目标 QPS")
	duration := flag.Duration("duration", 10*time.Second, "持续时间")
	concurrency := flag.Int("concurrency", 200, "最大并发")
	flag.Parse()

	if *rate <= 0 || *concurrency <= 0 {
		fmt.Fprintln(os.Stderr, "rate and concurrency must be positive")
		os.Exit(1)
	}

	url := strings.TrimRight(*base, "/") + *path
	transport := &http.Transport{
		MaxIdleConns:        *concurrency * 2,
		MaxIdleConnsPerHost: *concurrency * 2,
		MaxConnsPerHost:     *concurrency * 2,
		IdleConnTimeout:     90 * time.Second,
	}
	client := &http.Client{Transport: transport, Timeout: 5 * time.Second}

	ctx, cancel := context.WithTimeout(context.Background(), *duration)
	defer cancel()

	sem := make(chan struct{}, *concurrency)
	var wg sync.WaitGroup
	var mu sync.Mutex
	latencies := make([]time.Duration, 0, *rate*int(duration.Seconds()))
	errorsCount, statusErrors, dropped := 0, 0, 0

	ticker := time.NewTicker(time.Second / time.Duration(*rate))
	defer ticker.Stop()

	start := time.Now()
loop:
	for {
		select {
		case <-ctx.Done():
			break loop
		case <-ticker.C:
			select {
			case sem <- struct{}{}:
			default:
				dropped++
				continue
			}
			wg.Add(1)
			go func() {
				defer wg.Done()
				defer func() { <-sem }()

				req, err := http.NewRequest(http.MethodGet, url, nil)
				if err != nil {
					mu.Lock()
					errorsCount++
					mu.Unlock()
					return
				}
				if *token != "" {
					req.Header.Set("Authorization", "Bearer "+*token)
				}
				reqStart := time.Now()
				resp, err := client.Do(req)
				elapsed := time.Since(reqStart)

				mu.Lock()
				latencies = append(latencies, elapsed)
				if err != nil {
					errorsCount++
				} else if resp.StatusCode >= 400 {
					statusErrors++
				}
				mu.Unlock()

				if resp != nil {
					_, _ = io.Copy(io.Discard, resp.Body)
					_ = resp.Body.Close()
				}
			}()
		}
	}
	wg.Wait()
	elapsed := time.Since(start)

	sort.Slice(latencies, func(i, j int) bool { return latencies[i] < latencies[j] })
	total := len(latencies)
	fmt.Printf("url=%s total=%d duration=%s qps=%.1f dropped=%d network_errors=%d http_errors=%d\n",
		url, total, elapsed.Round(time.Millisecond),
		float64(total)/elapsed.Seconds(), dropped, errorsCount, statusErrors)
	if total > 0 {
		fmt.Printf("latency p50=%s p95=%s p99=%s max=%s\n",
			percentile(latencies, 0.50), percentile(latencies, 0.95),
			percentile(latencies, 0.99), latencies[total-1])
	}
	if errorsCount > 0 || statusErrors > 0 {
		os.Exit(1)
	}
}

func percentile(values []time.Duration, p float64) time.Duration {
	if len(values) == 0 {
		return 0
	}
	index := int(float64(len(values)-1) * p)
	return values[index]
}

package tracing

import (
	"context"
	"net/http"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/trace"

	"github.com/go-chi/chi/v5/middleware"
)

// Init 初始化 OTLP 追踪；endpoint 为空时返回 no-op，不产生额外开销。
func Init(ctx context.Context, serviceName, endpoint string) (func(context.Context) error, error) {
	if endpoint == "" {
		return func(context.Context) error { return nil }, nil
	}
	exporter, err := otlptracehttp.New(ctx)
	if err != nil {
		return nil, err
	}
	provider := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exporter),
		sdktrace.WithResource(resource.NewSchemaless(
			attribute.String("service.name", serviceName),
		)),
	)
	otel.SetTracerProvider(provider)
	otel.SetTextMapPropagator(propagation.TraceContext{})
	return provider.Shutdown, nil
}

// Middleware 为每个请求创建服务端 span，并把状态码写入属性。
func Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := otel.GetTextMapPropagator().Extract(r.Context(), propagation.HeaderCarrier(r.Header))
		ctx, span := otel.Tracer("openquizgo/http").Start(ctx,
			r.Method+" "+r.URL.Path,
			trace.WithSpanKind(trace.SpanKindServer))
		defer span.End()

		ww := middleware.NewWrapResponseWriter(w, r.ProtoMajor)
		next.ServeHTTP(ww, r.WithContext(ctx))

		span.SetAttributes(
			attribute.String("http.method", r.Method),
			attribute.String("http.target", r.URL.Path),
			attribute.Int("http.status_code", ww.Status()),
		)
		if ww.Status() >= 500 {
			span.SetStatus(codes.Error, "server error")
		}
	})
}

