import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

/**
 * 半透明全屏答题界面（P2-T6）。
 *
 * 关键：Activity 使用半透明主题，播放器只进入 paused 而不是被 stop；
 * 用户先按确认键暂停，App 监听到后再拉起本界面，因此无广告、进度保留。
 *
 * 题目来自服务端答题会话，答案在服务端判分并结算授权。
 */
class QuizActivity : ComponentActivity() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
    private lateinit var repository: QuizRepository
    private lateinit var engine: com.openquizgo.guard.domain.GuardEngine

    private var session: QuizSession? = null
    private var pending: List<SessionQuestion> = emptyList()
    private var questionIndex = 0
    private var answeredCount = 0

    /** 是否已把结果写回状态机（避免 onDestroy 覆盖）。 */
    private var outcomeApplied = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        repository = (application as GuardApplication).container.quizRepository
        engine = (application as GuardApplication).container.guardEngine
        engine.onQuizStarted()

        setContent {
            MaterialTheme(colorScheme = darkColorScheme()) {
                Surface(modifier = Modifier.fillMaxSize()) {
                    QuizRoot()
                }
            }
        }
        loadSession()
    }

    @Composable
    private fun QuizRoot() {
        var loading by remember { mutableStateOf(true) }
        var error by remember { mutableStateOf<String?>(null) }
        var question by remember { mutableStateOf<SessionQuestion?>(null) }
        var result by remember { mutableStateOf<AnswerResult?>(null) }
        var submitting by remember { mutableStateOf(false) }
        var outcome by remember { mutableStateOf<QuizOutcome?>(null) }
        var finished by remember { mutableStateOf(false) }

        // 由协程通过下面这些回调驱动 UI；使用 remember 保存的 setter。
        LocalUiBridge.loading = { loading = it }
        LocalUiBridge.error = { error = it }
        LocalUiBridge.question = { question = it }
        LocalUiBridge.result = { result = it }
        LocalUiBridge.submitting = { submitting = it }
        LocalUiBridge.outcome = { outcome = it }
        LocalUiBridge.finished = { finished = it }

        when {
            outcome != null -> ResultScreen(
                outcome = outcome!!,
                onClose = { finish() },
            )
            finished -> EmptyScreen("答题已结束")
            error != null -> {
                val message = error!!
                MessageScreen(
                    title = "网络异常",
                    detail = message,
                    primary = "重试" to {
                        error = null
                        loadSession()
                    },
                    secondary = "退出" to { finish() },
                )
            }
            loading -> MessageScreen(
                title = "正在获取题目…",
                detail = "请稍候",
                primary = null,
                secondary = null,
            )
            question != null -> QuestionScreen(
                question = question!!,
                index = questionIndex + 1,
                total = (session?.questions?.size ?: 0).coerceAtLeast(questionIndex + 1),
                result = result,
                submitting = submitting,
                onSelect = { optionId -> submitAnswer(optionId) },
                onNext = { advance() },
            )
            else -> EmptyScreen("暂无题目")
        }
    }

    private fun loadSession() {
        LocalUiBridge.loading?.invoke(true)
        LocalUiBridge.error?.invoke(null)
        scope.launch {
            runCatching { repository.startSession() }
                .onSuccess { started ->
                    session = started
                    pending = started.questions.filterNot { it.answered }
                    answeredCount = started.questions.size - pending.size
                    questionIndex = 0
                    GuardLog.i(
                        "quiz session=${started.sessionId} questions=${started.questions.size} " +
                            "pending=${pending.size}",
                    )
                    LocalUiBridge.loading?.invoke(false)
                    if (pending.isEmpty()) {
                        settle()
                    } else {
                        showCurrent()
                    }
                }
                .onFailure { error ->
                    GuardLog.w("quiz session failed: ${error.message}")
                    LocalUiBridge.loading?.invoke(false)
                    LocalUiBridge.error?.invoke(readable(error))
                }
        }
    }

    private fun showCurrent() {
        LocalUiBridge.result?.invoke(null)
        LocalUiBridge.submitting?.invoke(false)
        LocalUiBridge.question?.invoke(pending.getOrNull(questionIndex))
    }

    private fun submitAnswer(optionId: String) {
        val current = session ?: return
        val question = pending.getOrNull(questionIndex) ?: return
        if (LocalUiBridge.submitting?.invoke(true) == Unit) LocalUiBridge.submitting?.invoke(true)
        LocalUiBridge.submitting?.invoke(true)
        scope.launch {
            runCatching { repository.submitAnswer(current.sessionId, question.token, listOf(optionId)) }
                .onSuccess { answerResult ->
                    LocalUiBridge.submitting?.invoke(false)
                    LocalUiBridge.result?.invoke(answerResult)
                    answeredCount += 1
                    GuardLog.i(
                        "answer pos=$questionIndex correct=${answerResult.correct} " +
                            "score=${answerResult.score}/${answerResult.threshold}",
                    )
                }
                .onFailure { error ->
                    LocalUiBridge.submitting?.invoke(false)
                    GuardLog.w("answer failed: ${error.message}")
                    LocalUiBridge.error?.invoke(readable(error))
                }
        }
    }

    private fun advance() {
        if (questionIndex + 1 < pending.size) {
            questionIndex += 1
            showCurrent()
        } else {
            LocalUiBridge.question?.invoke(null)
            settle()
        }
    }

    private fun settle() {
        val current = session ?: return
        scope.launch {
            runCatching { repository.finish(current.sessionId) }
                .onSuccess { summary ->
                    val passed = summary.state == "passed" && summary.grant != null
                    GuardLog.i(
                        "quiz finished state=${summary.state} score=${summary.score}/${summary.passThreshold} " +
                            "grant=${summary.grant?.minutes ?: 0}",
                    )
                    outcomeApplied = true
                    if (passed) {
                        engine.onQuizPassed(summary.grant?.minutes ?: 0)
                    } else {
                        engine.onQuizFailed()
                    }
                    LocalUiBridge.outcome?.invoke(QuizOutcome(summary = summary, passed = passed))
                }
                .onFailure { error ->
                    GuardLog.w("quiz finish failed: ${error.message}")
                    LocalUiBridge.error?.invoke(readable(error))
                }
        }
    }

    private fun readable(error: Throwable): String = when (error) {
        is QuizApiException -> error.message
        else -> error.message ?: "未知错误"
    }

    override fun onDestroy() {
        if (!outcomeApplied) {
            engine.onQuizCancelled()
        }
        scope.cancel()
        super.onDestroy()
    }

    override fun finish() {
        if (outcomeApplied && LocalUiBridge.outcome?.invoke(null) != null) {
            // no-op, 保持可读性
        }
        super.finish()
    }

    companion object {
        /** 简易 UI 桥：由协程回调驱动 Compose 状态，避免在 Activity 中持有 Compose State。 */
        private object LocalUiBridge {
            var loading: ((Boolean) -> Unit)? = null
            var error: ((String?) -> Unit)? = null
            var question: ((SessionQuestion?) -> Unit)? = null
            var result: ((AnswerResult?) -> Unit)? = null
            var submitting: ((Boolean) -> Unit)? = null
            var outcome: ((QuizOutcome?) -> Unit)? = null
            var finished: ((Boolean) -> Unit)? = null
        }
    }
}

@Composable
private fun QuestionScreen(
    question: SessionQuestion,
    index: Int,
    total: Int,
    result: AnswerResult?,
    submitting: Boolean,
    onSelect: (String) -> Unit,
    onNext: () -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF0B0B0B))
            .padding(64.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            text = "答题时间 · 第 $index / $total 题",
            fontSize = 26.sp,
            color = Color(0xFFB0B0B0),
        )
        Spacer(Modifier.height(20.dp))
        Text(
            text = question.stem,
            fontSize = 44.sp,
            fontWeight = FontWeight.Bold,
            color = Color.White,
        )
        Spacer(Modifier.height(32.dp))

        if (result == null) {
            val options = question.options.orEmpty()
            if (options.isEmpty()) {
                Text("暂不支持该题型", fontSize = 24.sp, color = Color(0xFFFFC107))
            } else {
                options.forEach { option ->
                    Button(
                        onClick = { onSelect(option.id) },
                        enabled = !submitting,
                    ) {
                        Text(text = "${option.id}. ${option.text}", fontSize = 26.sp)
                    }
                    Spacer(Modifier.height(12.dp))
                }
            }
            if (submitting) {
                Spacer(Modifier.height(12.dp))
                Text("提交中…", fontSize = 20.sp, color = Color(0xFFB0B0B0))
            }
        } else {
            Text(
                text = if (result.correct) "回答正确" else "回答错误",
                fontSize = 40.sp,
                fontWeight = FontWeight.Bold,
                color = if (result.correct) Color(0xFF7CFF9B) else Color(0xFFFF7A7A),
            )
            result.explain?.takeIf { it.isNotBlank() }?.let {
                Spacer(Modifier.height(12.dp))
                Text(text = it, fontSize = 24.sp, color = Color(0xFFD0D0D0))
            }
            Spacer(Modifier.height(8.dp))
            Text(
                text = "当前得分 ${formatScore(result.score)} / 通过 ${formatScore(result.threshold)}",
                fontSize = 20.sp,
                color = Color(0xFF7CC7FF),
            )
            Spacer(Modifier.height(28.dp))
            Button(onClick = onNext) {
                Text(
                    text = if (result.remaining > 0) "下一题" else "查看结果",
                    fontSize = 26.sp,
                )
            }
        }
    }
}

@Composable
private fun ResultScreen(outcome: QuizOutcome, onClose: () -> Unit) {
    val summary = outcome.summary
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF0B0B0B))
            .padding(64.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            text = if (outcome.passed) "挑战成功" else "挑战失败",
            fontSize = 52.sp,
            fontWeight = FontWeight.Bold,
            color = if (outcome.passed) Color(0xFF7CFF9B) else Color(0xFFFF7A7A),
        )
        Spacer(Modifier.height(20.dp))
        Text(
            text = "答对 ${summary.correctCount} / ${summary.questionCount} 题 " +
                "· 得分 ${formatScore(summary.score)} / ${formatScore(summary.passThreshold)}",
            fontSize = 26.sp,
            color = Color(0xFFD0D0D0),
        )
        if (outcome.passed) {
            Spacer(Modifier.height(16.dp))
            Text(
                text = "本次获得 ${outcome.grantMinutes} 分钟观看时间",
                fontSize = 30.sp,
                color = Color(0xFFFFD54F),
            )
        } else {
            summary.grantError?.takeIf { it.isNotBlank() }?.let {
                Spacer(Modifier.height(12.dp))
                Text(text = it, fontSize = 20.sp, color = Color(0xFFFFC107))
            }
            Spacer(Modifier.height(12.dp))
            Text(
                text = "休息一下，稍后再来挑战吧",
                fontSize = 24.sp,
                color = Color(0xFFB0B0B0),
            )
        }
        Spacer(Modifier.height(40.dp))
        Row(horizontalArrangement = Arrangement.Center) {
            Button(onClick = onClose, modifier = Modifier.widthIn(min = 220.dp)) {
                Text(
                    text = if (outcome.passed) "继续观看" else "结束答题",
                    fontSize = 28.sp,
                )
            }
        }
    }
}

@Composable
private fun MessageScreen(
    title: String,
    detail: String,
    primary: Pair<String, () -> Unit>?,
    secondary: Pair<String, () -> Unit>?,
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF0B0B0B))
            .padding(64.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(text = title, fontSize = 40.sp, fontWeight = FontWeight.Bold, color = Color.White)
        Spacer(Modifier.height(16.dp))
        Text(text = detail, fontSize = 24.sp, color = Color(0xFFB0B0B0))
        Spacer(Modifier.height(40.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(24.dp)) {
            primary?.let { (label, action) ->
                Button(onClick = action) { Text(label, fontSize = 26.sp) }
            }
            secondary?.let { (label, action) ->
                Button(onClick = action) { Text(label, fontSize = 26.sp) }
            }
        }
    }
}

@Composable
private fun EmptyScreen(text: String) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF0B0B0B)),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(text = text, fontSize = 32.sp, color = Color(0xFFB0B0B0))
    }
}

private fun formatScore(value: Double): String =
    if (value == value.toInt().toDouble()) value.toInt().toString() else "%.1f".format(value)

content.text:
This LocalUiBridge approach is hacky and buggy:
- `LocalUiBridge.submitting?.invoke(true) == Unit` — weird leftover. Remove.
- `LocalUiBridge.loading` etc. are set inside composable during composition — setting mutable state inside composition triggers recomposition; assignment of lambdas each recomposition is side effect but allowed? Assigning to a var during composition is a side-effect; it won't crash but is bad practice. Better: use Compose state held in Activity via `mutableStateOf` properties, and have composable read them directly. That's much cleaner.

Let me restructure: Activity holds:
```kotlin
private var loading by mutableStateOf(true)
private var errorMessage by mutableStateOf<String?>(null)
private var currentQuestion by mutableStateOf<SessionQuestion?>(null)
private var answerResult by mutableStateOf<AnswerResult?>(null)
private var submitting by mutableStateOf(false)
private var outcome by mutableStateOf<QuizOutcome?>(null)
private var finishedScreen by mutableStateOf(false)
```
Compose reads these directly in setContent. Coroutines update them on Main dispatcher. Clean, no bridge.

Also `finish()` override weirdness: remove override, just show toast when outcome passed? Keep simple.

Also note: engine.onQuizStarted() transitions even if already QUIZZING (same). Good.

Also issue: when error occurs after answering some questions, "重试" calls loadSession() which creates a new session; server returns 409 active → resume existing session with answered flags → good. And completion? For finish failure, retry → loadSession resumes, then since pending empty -> settle again. Good.

But careful: when error during answer, retry recreates via resume. Fine.

One more: `QuestionScreen` total uses session size; good.

Also `onNext`: after last answered, `result.remaining > 0`? Server remaining = total - answered. Use that. Fine.

Let me rewrite QuizActivity more cleanly.

